const INTERP = {"c_Su":"Identity merge \u2014 ego + emotion fused, vitality surge, self-expression amplified","o_Su":"Will vs feeling \u2014 what you want opposes what you need, inner tug-of-war","s_Su":"Purpose friction \u2014 drive and emotion at cross purposes, frustrated self-expression","t_Su":"Harmonized will \u2014 purpose and feeling aligned, natural confidence","x_Su":"Gentle clarity \u2014 subtle confidence, identity support","c_Mo":"Emotional activation \u2014 feelings intensified, instincts dominant, reactive","o_Mo":"Emotional polarity \u2014 pulled between two feeling states, inner opposition","s_Mo":"Emotional pressure \u2014 feelings won't settle, restless inner friction","t_Mo":"Emotional flow \u2014 feelings move easily, intuition clear, comfort","x_Mo":"Subtle ease \u2014 gentle emotional support, background processing","c_Me":"Mind activation \u2014 thoughts charged, communication intense, mental overdrive","o_Me":"Mental tension \u2014 overthinking, communication breakdowns or breakthroughs","s_Me":"Mental friction \u2014 thoughts vs reality, miscommunication, nervous energy","t_Me":"Clear thinking \u2014 ideas flow, communication smooth, mental harmony","x_Me":"Mental ease \u2014 subtle insights, gentle clarity","c_Ve":"Heart activation \u2014 love, beauty, pleasure amplified, values front and center","o_Ve":"Desire tension \u2014 what you love vs what's available, relationship confrontation","s_Ve":"Values friction \u2014 wants clash with reality, love feels difficult","t_Ve":"Love flows \u2014 affection natural, beauty nourishing, creative ease","x_Ve":"Gentle pleasure \u2014 subtle sweetness, quiet appreciation","c_Ma":"Drive activation \u2014 energy surge, anger or passion, impulse to act","o_Ma":"Conflict confrontation \u2014 external opposition, battles, reactive anger","s_Ma":"Frustrated energy \u2014 action blocked, irritability, restless aggression","t_Ma":"Motivated action \u2014 energy channeled well, productive drive","x_Ma":"Gentle drive \u2014 subtle motivation, quiet initiative","c_Ju":"Expansion activation \u2014 growth, opportunity, excess, beliefs amplified","o_Ju":"Overextension \u2014 too much too fast, judgment tested, faith vs reality","s_Ju":"Growth tension \u2014 expansion blocked or forced, restless ambition","t_Ju":"Abundant flow \u2014 blessings arrive easily, optimism, natural growth","x_Ju":"Gentle opportunity \u2014 subtle luck, quiet expansion","c_Sa":"Structure pressure \u2014 restriction, discipline demanded, responsibility heavy","o_Sa":"Authority confrontation \u2014 external limits, accountability, consequences","s_Sa":"Blockage \u2014 stuck, burdened, effort feels futile, patience tested","t_Sa":"Mature grounding \u2014 discipline feels natural, stable foundation, earned reward","x_Sa":"Gentle discipline \u2014 subtle structure, quiet responsibility","c_Ur":"Lightning strike \u2014 sudden change, breakthrough, liberation, electric insight","o_Ur":"Disruption from outside \u2014 unexpected events, freedom vs stability","s_Ur":"Nervous tension \u2014 restless, needs change but can't find it, electric anxiety","t_Ur":"Intuitive breakthrough \u2014 sudden knowing, creative flash, welcome change","x_Ur":"Subtle awakening \u2014 quiet insight, gentle shift","c_Ne":"Dissolution \u2014 psychic flooding, boundaries gone, spiritual download or total fog","o_Ne":"Illusion confronted \u2014 clarity or confusion, reality vs dreams","s_Ne":"Psychic pressure \u2014 can't distinguish real from imagined, boundary crisis","t_Ne":"Spiritual flow \u2014 intuition heightened, creative vision, channeling clear","x_Ne":"Gentle psychic opening \u2014 dreams vivid, subtle spiritual support","c_Pl":"Power activation \u2014 transformation forced, deep purge, ancestral material surfaces","o_Pl":"Power confrontation \u2014 control issues, something buried demands attention","s_Pl":"Transformation pressure \u2014 old patterns dying, deep intensity, crisis potential","t_Pl":"Deep flow \u2014 transformation organic, power channeled constructively","x_Pl":"Subtle depth \u2014 quiet insight into patterns, gentle transformation","c_As":"Identity charged \u2014 emotional state visible, presence intensified","o_As":"Relationship mirror \u2014 projection onto others, what you feel you see outside","s_As":"Self-expression friction \u2014 inner state doesn't match outer presentation","t_As":"Aligned presence \u2014 inner and outer harmonized, natural expression","x_As":"Gentle alignment \u2014 subtle ease in self-presentation","c_Mc":"Purpose charged \u2014 career/public role emotionally activated, visible","o_Mc":"Root pull \u2014 private needs dominate, public role feels hollow","s_Mc":"Direction friction \u2014 career vs inner life tension","t_Mc":"Purpose flows \u2014 career and feeling aligned, work feels meaningful","x_Mc":"Gentle purpose support \u2014 quiet career momentum"};

const AN = { c:"conjunct", o:"opposition", s:"square", t:"trine", x:"sextile", _:"" };
const TN = { Su:"Sun", Mo:"Moon", Me:"Mercury", Ve:"Venus", Ma:"Mars", Ju:"Jupiter", Sa:"Saturn", Ur:"Uranus", Ne:"Neptune", Pl:"Pluto", As:"ASC", Mc:"MC", __:"" };
const AS = { c:"\u260c", o:"\u260d", s:"\u25a1", t:"\u25b3", x:"\u26b9", _:"" };
const PC = { Sun:"#F4A300", Mercury:"#8EC8E8", Venus:"#E87CA0", Mars:"#D94F3D", Jupiter:"#7B68C8", Saturn:"#8B7355", Uranus:"#3DC8C8", Neptune:"#5B7FD4", Pluto:"#9B4F6A" };
const PG = { Sun:"\u2609", Mercury:"\u263f", Venus:"\u2640", Mars:"\u2642", Jupiter:"\u2643", Saturn:"\u2644", Uranus:"\u2645", Neptune:"\u2646", Pluto:"\u2647" };

function h2r(hex) { return { r:parseInt(hex.slice(1,3),16), g:parseInt(hex.slice(3,5),16), b:parseInt(hex.slice(5,7),16) }; }

export default function TransitPressureSeraphe() {
  const [di, setDi] = useState(0);
  const [play, setPlay] = useState(false);
  const [spd, setSpd] = useState(80);
  const [hov, setHov] = useState(null);
  const [sel, setSel] = useState({});
  const cvs = useRef(null);
  const af = useRef(null);
  const lt = useRef(0);
  const N = DATA.d.length;
  const sc = Object.keys(sel).filter(k=>sel[k]).length;

  const tog = p => setSel(v=>({...v,[p]:!v[p]}));
  const clr = () => setSel({});

  useEffect(()=>{
    if(!play) return;
    let r=true;
    const s=t=>{if(!r)return;if(t-lt.current>spd){lt.current=t;setDi(v=>{if(v>=N-1){setPlay(false);return v;}return v+1;});}af.current=requestAnimationFrame(s);};
    af.current=requestAnimationFrame(s);
    return ()=>{r=false;cancelAnimationFrame(af.current);};
  },[play,spd,N]);

  const dt = DATA.d[di];
  const dObj = new Date(dt+"T12:00:00");
  const dStr = dObj.toLocaleDateString("en-US",{weekday:"short",month:"short",day:"numeric",year:"numeric"});

  const pd = useMemo(()=>DATA.p.map(p=>{
    const i=DATA.i[p][di], ac=DATA.a[p][di], ta=DATA.t[p][di];
    const prevI = di > 0 ? DATA.i[p][di-1] : i;
    const dir = i > prevI ? 1 : i < prevI ? -1 : 0;
    return {n:p, i, dir, s:DATA.s[p][di], g:DATA.g[p][di], asp:AN[ac]||"", sym:AS[ac]||"", tgt:TN[ta]||"", c:PC[p], gl:PG[p], interp:INTERP[ac+"_"+ta]||""};
  }),[di]);

  const tp = useMemo(()=>{
    const ps=sc>0?DATA.p.filter(p=>sel[p]):DATA.p;
    return ps.reduce((s,p)=>s+DATA.i[p][di],0);
  },[di,sel,sc]);

  useEffect(()=>{
    const c=cvs.current; if(!c)return;
    const x=c.getContext("2d"), W=c.width, H=c.height;
    x.clearRect(0,0,W,H);
    x.strokeStyle="rgba(255,255,255,0.04)"; x.lineWidth=1;
    for(let y=0;y<=H;y+=H/5){x.beginPath();x.moveTo(0,y);x.lineTo(W,y);x.stroke();}
    const ws=120, sd=Math.max(0,di-ws/2), ed=Math.min(N-1,sd+ws), vd=ed-sd;
    const ps=sc>0?DATA.p.filter(p=>sel[p]):DATA.p, filt=sc>0;
    for(const p of[...ps].reverse()){
      const cl=PC[p], rgb=h2r(cl);
      x.beginPath();
      for(let j=0;j<=vd;j++){const d=sd+j;if(d>=N)break;const px=(j/vd)*W,py=H-DATA.i[p][d]*H*0.85;j===0?x.moveTo(px,py):x.lineTo(px,py);}
      x.lineTo(W,H);x.lineTo(0,H);x.closePath();
      x.fillStyle=`rgba(${rgb.r},${rgb.g},${rgb.b},${filt?0.25:0.1})`;x.fill();
      x.beginPath();
      for(let j=0;j<=vd;j++){const d=sd+j;if(d>=N)break;const px=(j/vd)*W,py=H-DATA.i[p][d]*H*0.85;j===0?x.moveTo(px,py):x.lineTo(px,py);}
      x.strokeStyle=`rgba(${rgb.r},${rgb.g},${rgb.b},${filt?0.9:0.5})`;x.lineWidth=filt?2.5:1.5;x.stroke();
    }
    const px=((di-sd)/vd)*W;
    x.strokeStyle="rgba(255,255,255,0.7)";x.lineWidth=1.5;x.setLineDash([4,3]);
    x.beginPath();x.moveTo(px,0);x.lineTo(px,H);x.stroke();x.setLineDash([]);
    x.fillStyle="rgba(255,255,255,0.3)";x.font="11px monospace";x.textAlign="center";
    for(let j=0;j<=vd;j+=30){const d=sd+j;if(d>=N)break;const ppx=(j/vd)*W;const dd=new Date(DATA.d[d]+"T12:00:00");x.fillText(dd.toLocaleDateString("en-US",{month:"short",day:"numeric"}),ppx,H-4);}
  },[di,sel,sc,N]);

  const il=(v,dir)=>{
    if(v>=0.85) return "EXACT";
    if(dir>=0) return v>=0.6?"BUILDING \u2014 STRONG":v>=0.35?"BUILDING":v>=0.1?"APPROACHING":"QUIET";
    return v>=0.6?"SEPARATING \u2014 STRONG":v>=0.35?"SEPARATING":v>=0.1?"FADING":"QUIET";
  };
  const ic=v=>v>=0.85?"#FF3333":v>=0.6?"#FF8800":v>=0.35?"#DDAA00":v>=0.1?"#448866":"#333";

  const bs={background:"rgba(255,255,255,0.06)",border:`1px solid ${T.border}`,color:T.text,padding:"6px 12px",borderRadius:4,cursor:"pointer",fontSize:14,width:36,textAlign:"center"};
  const cs={padding:"4px 10px",borderRadius:12,border:"1px solid",cursor:"pointer",fontSize:11,fontWeight:600,letterSpacing:0.5,background:"transparent"};

  return (
    <div style={{maxWidth:1100,margin:"0 auto"}}>
      <div style={{textAlign:"center",marginBottom:20}}>
        <h1 style={{...serif,fontSize:22,fontWeight:600,letterSpacing:3,color:T.gold,margin:"0 0 4px 0"}}>TRANSIT PRESSURE MAP</h1>
        <div style={{...mono,fontSize:11,color:T.textMuted,letterSpacing:1}}>SERAPHE \u2014 LEO \u2609 / PISCES \u263d / SCORPIO ASC</div>
      </div>

      <div style={{display:"flex",justifyContent:"center",alignItems:"center",gap:20,marginBottom:16,flexWrap:"wrap"}}>
        <div style={{...serif,fontSize:18,fontWeight:600,color:T.text,letterSpacing:1}}>{dStr}</div>
        <div style={{...mono,background:`rgba(${Math.min(255,tp*40)},${Math.max(0,100-tp*10)},50,0.12)`,border:`1px solid rgba(${Math.min(255,tp*40)},${Math.max(0,100-tp*10)},50,0.25)`,padding:"6px 16px",borderRadius:4,fontSize:13}}>
          TOTAL PRESSURE: <span style={{color:ic(tp/(sc||9)),fontWeight:700}}>{tp.toFixed(1)}</span> / {sc||9}.0
        </div>
      </div>

      <div style={{background:"rgba(0,0,0,0.2)",borderRadius:6,border:`1px solid ${T.border}`,padding:10,marginBottom:16}}>
        <canvas ref={cvs} width={900} height={200} style={{width:"100%",height:200,display:"block"}} />
      </div>

      <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:16,justifyContent:"center",flexWrap:"wrap"}}>
        <button onClick={()=>setDi(0)} style={bs}>\u23ee</button>
        <button onClick={()=>setDi(Math.max(0,di-1))} style={bs}>\u25c0</button>
        <button onClick={()=>setPlay(!play)} style={{...bs,width:50,background:play?"rgba(255,60,60,0.2)":"rgba(60,255,60,0.15)"}}>{play?"\u23f8":"\u25b6"}</button>
        <button onClick={()=>setDi(Math.min(N-1,di+1))} style={bs}>\u25b6</button>
        <button onClick={()=>setDi(N-1)} style={bs}>\u23ed</button>
        <div style={{display:"flex",alignItems:"center",gap:6,marginLeft:8}}>
          <span style={{...mono,fontSize:10,color:T.textMuted}}>SPEED</span>
          <input type="range" min={10} max={300} value={300-spd} onChange={e=>setSpd(300-parseInt(e.target.value))} style={{width:70,accentColor:T.gold}} />
        </div>
        <input type="range" min={0} max={N-1} value={di} onChange={e=>setDi(parseInt(e.target.value))} style={{width:180,accentColor:T.gold,marginLeft:8}} />
      </div>

      <div style={{display:"flex",justifyContent:"center",gap:5,marginBottom:16,flexWrap:"wrap"}}>
        <button onClick={clr} style={{...cs,background:sc===0?`${T.gold}22`:"rgba(255,255,255,0.04)",borderColor:sc===0?T.gold:T.border,color:T.gold}}>ALL</button>
        {sc>0&&<span style={{...mono,fontSize:10,color:T.textMuted,alignSelf:"center"}}>{sc} selected</span>}
        {DATA.p.map(p=>{const rgb=h2r(PC[p]);return(
          <button key={p} onClick={()=>tog(p)} style={{...cs,background:sel[p]?`rgba(${rgb.r},${rgb.g},${rgb.b},0.18)`:"rgba(255,255,255,0.03)",borderColor:sel[p]?PC[p]:T.border,color:PC[p]}}>{PG[p]} {p}</button>
        );})}
      </div>

      <div style={{display:"flex",flexDirection:"column",gap:2}}>
        {pd.map(p=>{
          const act=p.i>0.05, hd=hov===p.n, isSel=sc===0||sel[p.n], bw=Math.max(0,p.i*100);
          return(
            <div key={p.n} onMouseEnter={()=>setHov(p.n)} onMouseLeave={()=>setHov(null)} onClick={()=>tog(p.n)}
              style={{borderRadius:6,cursor:"pointer",background:hd?T.bgHover:"transparent",transition:"all 0.2s",opacity:!isSel?0.2:(act?1:0.35),padding:"2px 0"}}>
              <div style={{display:"flex",alignItems:"center",gap:0}}>
                <div style={{display:"flex",alignItems:"center",gap:6,padding:"4px 8px",minWidth:90}}>
                  <div style={{fontSize:18,width:22,textAlign:"center",color:p.c}}>{p.gl}</div>
                  <div style={{...mono,fontSize:11,fontWeight:600,color:p.c,letterSpacing:1}}>{p.n}</div>
                </div>
                <div style={{...mono,flex:"0 0 100px",fontSize:10,color:T.textMuted,padding:"0 6px",whiteSpace:"nowrap"}}>{p.g}\u00b0 {p.s}</div>
                <div style={{flex:1,padding:"2px 0"}}>
                  <div style={{width:"100%",height:20,background:"rgba(255,255,255,0.03)",borderRadius:3,overflow:"hidden",position:"relative"}}>
                    <div style={{width:`${bw}%`,height:"100%",background:`linear-gradient(90deg,${p.c}22,${p.c}88)`,borderRadius:3,transition:"width 0.15s",boxShadow:p.i>0.7?`0 0 12px ${p.c}44`:"none"}} />
                    {act&&<div style={{...mono,position:"absolute",top:0,left:8,height:"100%",display:"flex",alignItems:"center",fontSize:10,color:"rgba(255,255,255,0.7)",letterSpacing:1}}>{il(p.i,p.dir)}</div>}
                  </div>
                </div>
                <div style={{...mono,flex:"0 0 170px",fontSize:11,color:act?T.textDim:T.textMuted,padding:"0 6px",textAlign:"right",whiteSpace:"nowrap"}}>
                  {act&&p.asp?<><span style={{color:p.c}}>{p.sym}</span> {p.asp} <span style={{color:T.textMuted}}>natal</span> <span style={{color:T.gold}}>{p.tgt}</span></>:"\u2014"}
                </div>
                <div style={{...mono,flex:"0 0 40px",fontSize:12,fontWeight:700,textAlign:"right",color:ic(p.i),padding:"0 8px 0 0"}}>{(p.i*100).toFixed(0)}%</div>
              </div>
              {act&&p.interp&&<div style={{padding:"0 8px 4px 98px",fontSize:10,color:T.textMuted,fontStyle:"italic",lineHeight:1.4,letterSpacing:0.3}}>{p.interp}</div>}
            </div>
          );
        })}
      </div>

      {(()=>{
        const top=pd.filter(p=>p.i>0.1&&p.interp).sort((a,b)=>b.i-a.i)[0];
        if(!top)return null;
        const rgb=h2r(top.c);
        return(
          <div style={{marginTop:12,padding:"10px 14px",borderRadius:6,background:`rgba(${rgb.r},${rgb.g},${rgb.b},0.06)`,border:`1px solid rgba(${rgb.r},${rgb.g},${rgb.b},0.15)`}}>
            <div style={{...mono,fontSize:10,color:T.gold,letterSpacing:1,marginBottom:4}}>DOMINANT TRANSIT</div>
            <div style={{fontSize:13,color:T.textDim,lineHeight:1.5}}>
              <span style={{color:top.c,fontWeight:700}}>{top.gl} {top.n}</span> at {top.g}\u00b0 {top.s}{" "}
              <span style={{color:T.textMuted}}>{top.sym} {top.asp}</span> natal <span style={{color:T.gold}}>{top.tgt}</span>
              {" \u2014 "}<span style={{fontStyle:"italic"}}>{top.interp}</span>
            </div>
          </div>
        );
      })()}

      <div style={{marginTop:16,padding:12,background:T.bgCard,borderRadius:6,border:`1px solid ${T.border}`}}>
        <div style={{...mono,fontSize:11,color:T.gold,letterSpacing:1,marginBottom:8}}>NATAL CHART REFERENCE</div>
        <div style={{display:"flex",flexWrap:"wrap",gap:"4px 16px",...mono,fontSize:11,color:T.textMuted}}>
          {Object.entries(DATA.n).map(([k,[l,s,d]])=><span key={k}><span style={{color:PC[k]||T.textMuted}}>{PG[k]||"\u2b21"}</span> {k} {Math.round(d)}\u00b0 {s}</span>)}
        </div>
      </div>
    </div>
  );
}
